from itertools import permutations

def orders(people, facts):
    """All tallest-first orders consistent with facts [(x, y)] meaning x is taller than y."""
    return [p for p in permutations(people) if all(p.index(x) < p.index(y) for x, y in facts)]

# Constructed: P taller than Q but shorter than R; S shorter than Q; T taller than R.
facts = [("P", "Q"), ("R", "P"), ("Q", "S"), ("T", "R")]
res = orders("PQRST", facts)
assert res == [tuple("TRPQS")]                      # one chain: T > R > P > Q > S
tallest = {o[0] for o in res}
middle = {o[2] for o in res}
assert tallest == {"T"} and middle == {"P"}
options = {"A": "R", "B": "T", "C": "P", "D": "S"}
assert [k for k, v in options.items() if {v} == tallest] == ["B"]

# Constructed: A > B, A > C, C > D -> the tallest is fixed (A) but the 2nd is not (B or C)
res = orders("ABCD", [("A", "B"), ("A", "C"), ("C", "D")])
assert {o[0] for o in res} == {"A"} and {o[1] for o in res} == {"B", "C"}
